import { test, expect } from "@playwright/test";

test.describe("BUG: Docs Deployment Login Wall", () => {
  test("docs page should be publicly accessible without authentication", async ({ page }) => {
    // Navigate to docs page WITHOUT authentication
    await page.goto("/docs");

    // Wait for page to load
    await page.waitForLoadState("domcontentloaded");

    // The bug: docs page should NOT redirect to login
    // Currently it does redirect to /login?redirect=%2Fdocs
    const currentUrl = page.url();
    expect(currentUrl).not.toContain("/login");

    // Should see docs content, not login form
    const loginForm = page.locator('input[placeholder*="Enter password"]');
    await expect(loginForm).not.toBeVisible();

    // Should see some docs content (this will fail until bug is fixed)
    const docsContent = page.locator('body');
    const bodyText = await docsContent.textContent();
    expect(bodyText).toContain("docs"); // Very basic check that we're on a docs page
  });

  test("docs page emits no console errors when accessed publicly", async ({ page }) => {
    const consoleErrors: string[] = [];
    const pageErrors: string[] = [];

    // Set up error listeners BEFORE navigation
    page.on("console", (msg) => {
      if (msg.type() === "error") {
        consoleErrors.push(msg.text());
      }
    });

    page.on("pageerror", (err) => {
      pageErrors.push(err.message);
    });

    // Navigate to docs page WITHOUT authentication
    await page.goto("/docs");
    await page.waitForLoadState("domcontentloaded");

    // Wait for any async operations to complete
    await page.waitForTimeout(3000);

    // Filter out known harmless errors (same pattern as other console error tests)
    const realErrors = consoleErrors.filter(err =>
      !err.includes("React DevTools") &&
      !err.includes("defaultProps") &&
      !err.includes("Warning:") &&
      !err.includes("[HMR]") &&
      !err.includes("Download the React DevTools") &&
      !err.includes("Quirks Mode") // Browser warning, not a real error
    );

    // Assert no real console errors (this should pass even in broken state)
    expect(realErrors, `Expected no console errors, but found ${realErrors.length} error(s): ${realErrors.join("; ")}`).toHaveLength(0);
    expect(pageErrors, `Expected no page errors, but found ${pageErrors.length} error(s): ${pageErrors.join("; ")}`).toHaveLength(0);
  });
});

