import { test, expect } from "@playwright/test";
const { authenticate } = require("./helper");

test.describe("BUG: Docs Not Deployed to Vercel", () => {
  test("docs route should redirect to login when not authenticated", async ({ page }) => {
    // Navigate to docs page WITHOUT authentication
    await page.goto("/docs");

    // Should redirect to login page with redirect parameter
    await page.waitForURL("**/login?redirect=%2Fdocs");

    const currentUrl = page.url();
    expect(currentUrl).toContain("/login");
    expect(currentUrl).toContain("redirect=%2Fdocs");

    // Should see login form
    const loginForm = page.locator('input[placeholder*="Enter password"]');
    await expect(loginForm).toBeVisible();
  });

  test("docs page should load content when authenticated (currently fails due to missing files)", async ({ page }) => {
    // Authenticate first (docs should be protected)
    await authenticate(page);

    // Navigate to docs page
    await page.goto("/docs");

    // Wait for page to load
    await page.waitForLoadState("domcontentloaded");

    // The bug: docs page should load content, but currently fails
    // because docs/plans directories aren't included in Vercel deployment

    // Wait for API call to complete (or fail)
    await page.waitForTimeout(3000);

    // Check if we get an error from the API
    const errorElement = page.locator('text=/Error:/');
    const hasError = await errorElement.isVisible().catch(() => false);

    if (hasError) {
      // If there's an error, it should be about missing files (this is the bug)
      const errorText = await errorElement.textContent();
      expect(errorText).toContain("Failed to generate docs manifest");
    } else {
      // If no error, check that we have some content
      const body = page.locator('body');
      const bodyText = await body.textContent();

      // Should have loaded some documents
      expect(bodyText).toBeTruthy();
      expect(bodyText!.length).toBeGreaterThan(100); // Should have substantial content
    }
  });

  test("docs API should return manifest data when authenticated", async ({ page }) => {
    // This test will fail in deployment because the API can't read the files
    const response = await page.request.get("/api/docs/manifest");
    expect(response.status()).toBe(200);

    const data = await response.json();
    expect(data).toHaveProperty("docs");
    expect(Array.isArray(data.docs)).toBe(true);

    // Should have some documents
    expect(data.docs.length).toBeGreaterThan(0);
  });
});

