+const fs = require("node:fs");
+const path = require("node:path");
+
+/**
+ * Vercel / serverless runtime does not have access to repo-root files outside `src/`.
+ * This script copies `../docs` and `../plans` into `src/docs` and `src/plans` during the build,
+ * so `/api/docs/*` can read them at runtime.
+ *
+ * Important:
+ * - We ONLY run this in Vercel/CI to avoid dirtying local working trees by default.
+ * - We skip symlinks (they don't work reliably in Vercel).
+ */
+
+const SHOULD_RUN = process.env.VERCEL === "1" || process.env.CI === "true";
+if (!SHOULD_RUN) {
+  console.log("[prepare-docs] skipping (not Vercel/CI)");
+  process.exit(0);
+}
+
+const SRC_ROOT = process.cwd(); // expected: /.../rockcap/src
+const REPO_ROOT = path.resolve(SRC_ROOT, "..");
+
+const SOURCES = [
+  { name: "docs", from: path.join(REPO_ROOT, "docs"), to: path.join(SRC_ROOT, "docs") },
+  { name: "plans", from: path.join(REPO_ROOT, "plans"), to: path.join(SRC_ROOT, "plans") },
+];
+
+const SKIP_DIRS = new Set([
+  ".git",
+  "node_modules",
+  "data",
+  "site",
+  "test-results",
+  "playwright-report",
+  ".playwright-mcp",
+  "transcripts",
+]);
+
+function ensureDir(p) {
+  fs.mkdirSync(p, { recursive: true });
+}
+
+function emptyDir(p) {
+  if (!fs.existsSync(p)) return;
+  for (const entry of fs.readdirSync(p)) {
+    fs.rmSync(path.join(p, entry), { recursive: true, force: true });
+  }
+}
+
+function copyDir(srcDir, destDir) {
+  if (!fs.existsSync(srcDir)) return;
+  const entries = fs.readdirSync(srcDir, { withFileTypes: true });
+  for (const entry of entries) {
+    if (entry.name.startsWith(".") && entry.name !== ".pages") continue;
+    if (SKIP_DIRS.has(entry.name)) continue;
+
+    const srcPath = path.join(srcDir, entry.name);
+    const destPath = path.join(destDir, entry.name);
+
+    const st = fs.lstatSync(srcPath);
+    if (st.isSymbolicLink()) {
+      // avoid symlinks; they break in Vercel packaging
+      continue;
+    }
+
+    if (st.isDirectory()) {
+      ensureDir(destPath);
+      copyDir(srcPath, destPath);
+    } else if (st.isFile()) {
+      ensureDir(path.dirname(destPath));
+      fs.copyFileSync(srcPath, destPath);
+    }
+  }
+}
+
+for (const s of SOURCES) {
+  console.log(`[prepare-docs] copying ${s.name}: ${s.from} -> ${s.to}`);
+  ensureDir(s.to);
+  emptyDir(s.to);
+  copyDir(s.from, s.to);
+}
+
+console.log("[prepare-docs] done");
